  const query=el('local-manager-search').value.trim().toLowerCase(),rows=(state.local_models||[]).filter(row=>[row.name,row.path,row.repo].join(' ').toLowerCase().includes(query));const list=el('local-manager-list'),signature=JSON.stringify([rows,query,en(),changing,state.status,state.busy,state.model_path,state.model_discovery]);if(signature===managerSignature)return;managerSignature=signature;list.replaceChildren();
  el('local-manager-notice').textContent=state.model_discovery?.status==='scanning'?text('Ricerca in background nei dischi locali. I modelli già rilevati restano disponibili.','Background search of local drives. Previously found models remain available.'):state.model_discovery?.status==='error'?state.model_discovery.error:rows.length+' '+text('modelli · la rimozione richiede conferma','models · removal requires confirmation');
  for(const row of rows){const card=document.createElement('article'),info=document.createElement('div'),title=document.createElement('strong'),size=document.createElement('span'),path=document.createElement('small'),remove=document.createElement('button');card.className='local-manager-row';title.textContent=row.name;size.textContent=number2(row.bytes/2**30)+' GiB · '+(row.format||'GGUF');path.textContent=row.path;info.append(title,size,path);remove.type='button';remove.className='st-btn local-manager-delete';remove.textContent=text('Elimina dal disco','Delete from disk');remove.setAttribute('aria-label',text('Elimina dal disco: ','Delete from disk: ')+row.name);remove.disabled=changing||state.status==='loading'||state.busy||state.model_path===row.path;remove.onclick=async()=>{remove.disabled=true;try{await removeLocal(row);renderLocalManager();el('local-manager-notice').textContent=el('backend-error').textContent||text('Operazione annullata.','Operation cancelled.');}finally{remove.disabled=changing||state.model_path===row.path;}};card.append(info,remove);list.append(card);}
