 configDialog.innerHTML='<header class="catalogue-dialog-head"><div><h2 id="backend-config-dialog-title">Configura inferenza e strumenti</h2><p id="backend-config-model"></p></div><button type="button" id="backend-config-close" aria-label="Close">×</button></header><div class="backend-config-scroll"><div id="backend-config-memory" class="backend-config-memory"></div></div>';
