 function backendGraph(points,label){
  if(!points.length)return `<p class="backend-chart-empty">${text('Il grafico si popola durante il caricamento e le richieste.','The chart fills during loading and requests.')}</p>`;
  const max=Math.max(1,...points.map(p=>p.y)),path=points.map((p,i)=>`${12+i*376/Math.max(1,points.length-1)},${88-p.y/max*66}`).join(' ');
  return `<svg viewBox="0 0 400 110" role="img" aria-label="${esc(label)}"><line x1="12" x2="388" y1="88" y2="88" stroke="var(--st-line)"/><polyline points="${path}" fill="none" stroke="var(--st-accent)" stroke-width="2.5"/><circle cx="${points.length>1?388:12}" cy="${88-points.at(-1).y/max*66}" r="3.5" fill="var(--st-accent)"/><text x="12" y="105" fill="var(--st-ink-muted)" font-size="10">${esc(label)}</text><text x="388" y="16" text-anchor="end" fill="var(--st-accent-text)" font-size="12">${points.at(-1).y.toFixed(1)}</text></svg>`;
 }
