 function showMemoryPreview(data,row){
   if(!row){el('backend-memory-preview').innerHTML='';el('backend-config-memory').textContent=text('Stima non disponibile per il contesto effettivo; consulta le risorse misurate.','No estimate for the effective context; see measured resources.');return;}
   if(row){const kvKnown=row.kv_gib!=null,w=data.weights_gib,k=row.kv_gib||0,c=row.compute_buffers_gib||1,total=w+k+c+row.cache_ram_gib+row.checkpoint_ram_gib,scale=Math.max(total,data.gpu_free_gib||total),bar=(value,color)=>`<span style="width:${100*value/scale}%;background:${color}"></span>`;
    const gpu=row.gpu_estimated_alloc_gib,ram=row.ram_estimated_upper_gib,combined=gpu!=null&&ram!=null?gpu+ram:null;
    el('backend-estimate-total').textContent=combined!=null?(kvKnown?'~':'≥ ')+combined.toLocaleString(en()?'en-US':'it-IT',{maximumFractionDigits:1})+' GiB':'—';
    const budget=data.gpu_budget_gib||data.gpu_free_gib,usage=gpu!=null&&budget?Math.min(100,100*gpu/budget):0,ramUse=ram!=null?Math.min(100,100*ram/data.ram_free_gib):0;
    el('backend-estimate-metrics').innerHTML=`<div class="backend-budget-card"><span>${text('GPU · memoria video','GPU · video memory')}</span><b>${gpu!=null?number2(gpu)+' GiB':'—'}</b><meter min="0" max="100" value="${usage}"></meter><small>${text('Tetto configurato','Configured ceiling')}: ${budget?number2(budget)+' GiB':text('Modalità CPU','CPU mode')}</small><small>${text('Libera all’analisi','Free when analysed')}: ${data.gpu_free_gib!=null?number2(data.gpu_free_gib)+' GiB':'—'}</small></div><div class="backend-budget-card"><span>${text('RAM · memoria del PC','RAM · system memory')}</span><b>${ram!=null?number2(ram)+' GiB':'—'}</b><meter min="0" max="100" value="${ramUse}"></meter><small>${text('Disponibile all’analisi','Available when analysed')}: ${number2(data.ram_free_gib)} GiB</small></div><p class="backend-estimate-status ${row.fits?'is-fit':'is-over'}">${!kvKnown?text('Stima parziale: cache KV da verificare','Partial estimate: KV cache requires verification'):row.fits?text('Configurazione entro i margini stimati','Configuration within estimated margins'):text('Memoria insufficiente per questa configurazione','Insufficient memory for this configuration')}</p><p class="backend-budget-note">${text('Stima prudente, non uso misurato. La RAM può includere copie temporanee dei pesi. Il caricamento ricontrolla le risorse.','Conservative estimate, not measured usage. RAM may include temporary copies of the weights. Loading rechecks available resources.')}</p>`;
    const budgetCards=el('backend-estimate-metrics').querySelectorAll('.backend-budget-card');
    budgetCards[0].querySelector('span').textContent=text('GPU richiesta · stima','GPU required · estimate');
    budgetCards[1].querySelector('span').textContent=text('RAM richiesta · stima','RAM required · estimate');
    for(const [card,needed,capacity] of [[budgetCards[0],gpu,budget],[budgetCards[1],ram,data.ram_free_gib]]){
      if(needed!=null&&capacity){const margin=document.createElement('small');margin.className='backend-budget-remaining';margin.textContent=text('Resterebbero: ','Would remain: ')+number2(capacity-needed)+' GiB';card.append(margin);}
    }
    el('backend-config-memory').textContent=text('Stima modello totale: ','Estimated model total: ')+(kvKnown?'':'≥ ')+number2(total)+' GiB · KV '+(kvKnown?number2(k):'—')+' GiB · '+row.context_per_slot.toLocaleString(en()?'en-US':'it-IT')+' '+text('token per slot','tokens per slot')+(row.mixed_cpu_gpu?' · GPU + RAM':'');
    el('backend-memory-preview').innerHTML=`<div class="backend-memory-head"><strong>${text('Stima risorse al caricamento','Estimated loading resources')}</strong><b>${kvKnown?'':'≥ '}${number2(total)} GiB ${text('totali','total')}</b></div><div class="backend-memory-bar">${bar(w,'var(--st-accent)')}${bar(k,'#40b8e8')}${bar(c,'#d7a54d')}</div><dl>${data.gpu_budget_gib?`<div><dt>${text('Budget GPU','GPU budget')}</dt><dd>${number2(data.gpu_budget_gib)} GiB</dd></div>`:''}<div><dt>${text('Pesi','Weights')}</dt><dd>${number2(w)} GiB</dd></div><div><dt>KV · ${esc(data.kv_type)} · ${data.slots} slot</dt><dd>${kvKnown?number2(k)+' GiB':text('Non stimabile','Not estimable')}</dd></div><div><dt>${text('Buffer stimati','Estimated buffers')}</dt><dd>~${number2(c)} GiB</dd></div><div><dt>${text('Checkpoint RAM · limite prudente','RAM checkpoints · conservative bound')}</dt><dd>~${number2(row.checkpoint_ram_gib)} GiB</dd></div><div><dt>${text('Cache RAM massima','Maximum RAM cache')}</dt><dd>${number2(row.cache_ram_gib)} GiB</dd></div><div><dt>${text('RAM richiesta con margine','Required RAM with margin')}</dt><dd>${number2(row.ram_required_gib)} GiB</dd></div></dl><small>${text('Stima dai metadati, non memoria misurata. Budget VRAM e margini verificati all’avvio.','Metadata estimate, not measured usage. VRAM budget and margins checked at startup.')}${data.slots>1?' '+text('Il gateway della dashboard mantiene richieste serializzate.','The dashboard gateway keeps requests serialised.'):''}</small>`;
   }

 }
